COPY={}
def page(n,en,es,se,ss,ce,cs,fe,fs):
 COPY[f'DD-{n:03d}']={'en':dict(title=en[0],intro=en[1],sections=se,checklist=ce,faq=fe),'es':dict(title=es[0],intro=es[1],sections=ss,checklist=cs,faq=fs)}
page(83,('Puppy exercise: follow comfort and individual guidance','Plan exploration, easy play and rest around your growing Doberman’s needs. Physical size does not establish readiness for repetitive exertion, and a minutes-per-month formula cannot assess your individual puppy.'),('Ejercicio del cachorro: comodidad y orientación individual','Organiza exploración, juego fácil y descanso según necesidades. Tamaño no demuestra preparación para esfuerzo repetitivo, y una fórmula de minutos por mes no valora a tu cachorro.'),[
('Discuss the activity plan at a puppy visit','Ask your veterinary team about growth, health, surfaces and appropriate activity for this dog. Discuss any restrictions and safe socialization opportunities. Avoid treating another puppy’s routine or a breed weight estimate as a prescription. Record the advice and how to reassess as your puppy develops.'),('Distinguish choice from repeated exertion','Easy exploration with opportunities to pause is different from repeatedly encouraging sprints, jumps or long forced outings. Keep activities manageable and observe willingness to continue. A puppy who follows an excited person may not regulate every activity safely; adults still need to manage intensity and surroundings.'),('Make rest part of the session','Choose stable footing and suitable surroundings, with water and a comfortable resting option. Stop for limping, unusual fatigue, reluctance or discomfort and seek veterinary advice. Do not keep increasing effort because your puppy remains excited or because an online schedule says more exercise is due.'),('A worked activity record','Example: setting—quiet secure area; activity—gentle exploration; choice—puppy pauses and returns to rest; next step—repeat an easy opportunity rather than adding distance. Record what actually happened. This example is not a measured exercise allowance, a growth-plate assessment or a promise of injury prevention.'),('Adapt before adding new demands','Review the plan before introducing sustained running, repetitive jumping or a demanding sport. Progress depends on the individual and professional advice, not only the calendar. Use short skill practice and safe enrichment to support everyday life without replacing necessary care or comfortable rest.')],[
('Consulta el plan','Pregunta crecimiento, salud, superficies y actividad apropiada. Revisa restricciones y socialización segura. La rutina de otro cachorro no prescribe la tuya. Anota orientación y revisión conforme crece.'),('Distingue elección y repetición','Explorar con pausas difiere de provocar carreras, saltos o salidas largas forzadas. Observa voluntad de continuar. Seguir a una persona excitada no garantiza autorregulación: el adulto controla intensidad y entorno.'),('Incluye descanso','Elige suelo estable, agua y descanso. Para ante cojera, fatiga inusual, rechazo o molestias y consulta. No aumentes esfuerzo solo por excitación o una tabla.'),('Ejemplo de registro','Lugar: zona tranquila segura. Actividad: exploración suave. Elección: pausa y descansa. Próximo paso: repetir fácilmente, no añadir distancia. Es observación, no límite medido, valoración de crecimiento ni garantía.'),('Revisa nuevas exigencias','Consulta antes de carrera sostenida, saltos repetidos o deporte exigente. Depende del individuo, no solo fecha. Habilidades breves y enriquecimiento apoyan rutina sin sustituir cuidados y descanso.')],['Ask about individual activity and restrictions.','Choose comfortable footing and manageable exploration.','Observe pauses, movement and willingness.','Stop for discomfort and review new demands professionally.'],['Consulta actividad y restricciones individuales.','Elige suelo cómodo y exploración manejable.','Observa pausas, movimiento y voluntad.','Para ante molestias y revisa nuevas exigencias.'],[('Is five minutes per month of age a reliable prescription?','A formula cannot assess this puppy’s health, activity or circumstances. Ask for individual guidance.'),('Does a tired puppy need more exercise to settle?','Check comfort, rest opportunities and routine rather than automatically adding effort.')],[('¿Cinco minutos por mes prescribe ejercicio?','No valora salud, actividad ni circunstancias. Consulta orientación individual.'),('¿Necesita más ejercicio si está cansado?','Revisa comodidad, descanso y rutina sin añadir esfuerzo automáticamente.')])
page(88,('Heat and cold: plan around conditions, not one cutoff','Weather safety depends on exposure, humidity, activity, surfaces and the individual dog. A short coat or a jacket does not establish a universally safe temperature or replace observing comfort.'),('Calor y frío: valora condiciones, no un solo límite','Seguridad depende de exposición, humedad, actividad, superficies y perro. Pelo corto o abrigo no establecen temperatura universalmente segura ni sustituyen observar comodidad.'),[
('Assess the outing before leaving','Consider shade, water, wind, wetness, surface conditions, route length and options to return early. Ask your veterinarian about individual risk and any health restrictions. Air temperature alone does not describe hot pavement or the effects of humidity and exertion.'),('Reduce heat exposure and watch the dog','Choose cooler conditions and easier activities, with access to shade and water. Never leave your dog unattended in a hot vehicle. Unusual panting, weakness or other worrying changes require stopping activity and contacting veterinary help. Suspected heatstroke is urgent; do not wait for a complete checklist.'),('Keep cold-weather comfort practical','Provide dry shelter and opportunities to warm up, and adapt duration to the individual response. If using a coat, check fit, free movement and tolerance rather than assuming clothing makes any outing safe. Wetness and wind can change the experience, and cold-related discomfort needs attention.'),('A worked weather decision','Example: the planned walk offers little shade and hot surfaces. Change the route or timing and choose an easier alternative instead of relying on a weather-app number. Record conditions and your dog’s response. This is a decision example, not a threshold chart or a guarantee that the revised outing is safe.'),('Prepare an urgent-care route','Keep clinic and appropriate emergency contacts accessible. For collapse, breathing difficulty or suspected weather-related illness, seek urgent veterinary instructions and arrange assessment. Do not improvise medication or delay care while researching a home treatment. Review the future activity plan after urgent concerns are addressed.')],[
('Valora salida antes','Considera sombra, agua, viento, humedad, suelo, duración y regreso. Consulta riesgo individual y restricciones. Temperatura del aire no describe pavimento ni efecto de esfuerzo y humedad.'),('Reduce calor y observa','Elige condiciones frescas y tareas fáciles con sombra y agua. Nunca lo dejes desatendido en coche caliente. Jadeo inusual, debilidad u otros cambios exigen parar y contactar ayuda. Sospecha de golpe de calor es urgente sin esperar lista completa.'),('Organiza comodidad ante frío','Ofrece refugio seco y posibilidad de calentarse. Adapta duración. Abrigo requiere ajuste, movimiento y tolerancia; no vuelve segura cualquier salida. Viento y humedad cambian experiencia.'),('Ejemplo de decisión','Ruta prevista con poca sombra y suelo caliente: cambia lugar u horario y elige alternativa fácil, sin basarte solo en aplicación meteorológica. Anota condiciones y respuesta. No es tabla de límites ni garantía.'),('Prepara ruta de urgencias','Guarda clínica y urgencias. Colapso, dificultad respiratoria o enfermedad sospechada requieren instrucciones urgentes y valoración. No improvises medicamentos ni retrases ayuda investigando. Revisa plan futuro después.')],['Check surfaces, exposure, water and an early return option.','Adapt activity to the dog and conditions.','Treat suspected heatstroke as urgent.','Keep veterinary contacts available.'],['Revisa suelo, exposición, agua y regreso.','Adapta actividad a perro y condiciones.','Trata golpe de calor sospechado como urgente.','Conserva contactos veterinarios.'],[('Does a coat make every cold walk safe?','No. Check conditions, fit and your dog’s response.'),('Can one temperature tell me whether exercise is safe?','No. Exposure, humidity, surfaces, exertion and individual risk also matter.')],[('¿Un abrigo hace segura cualquier salida?','No. Valora condiciones, ajuste y respuesta.'),('¿Una temperatura determina seguridad?','No. También importan exposición, humedad, suelo, esfuerzo y riesgo.')])
page(93,('Car travel: verify restraint evidence and prepare comfortable stops','Choose transport equipment using documented fit, installation and independent testing information. A product’s safety claim does not replace checking the exact model and setting up a manageable journey.'),('Viaje en coche: verifica equipo y prepara paradas','Elige por ajuste, instalación y pruebas independientes documentadas. Una promesa de seguridad no sustituye verificar modelo y organizar trayecto manejable.'),[
('Check the exact equipment and evidence','Ask for the model, size range, installation instructions and any independent certification or test record. Compare the exact product with the testing organization’s published information. A similar name, marketing video or claim about materials is not evidence that this model passed a test.'),('Install according to the documented setup','Follow instructions for the vehicle and restraint, including appropriate attachment points and permitted accessories. Do not improvise extensions or anchor points: the Center for Pet Safety warns that extra movement can increase injury risk. A walking harness is not automatically a vehicle restraint.'),('Introduce the journey gradually','Start with comfortable experiences around the parked vehicle and correctly fitted equipment, then manageable journeys when your dog is ready. Watch for distress or travel-related illness and ask your veterinarian about concerns. Do not leave the dog unattended in the vehicle, and never treat an open window as heat protection.'),('A worked pre-trip check','Example: a harness is advertised as crash tested, but the listing omits the size and installation used. Record those gaps and verify the model with the manufacturer and independent testing source before relying on the claim. This guide does not conduct or certify a crash test.'),('Plan stops and secure transitions','Prepare water, suitable toilet opportunities and a safe place to stop. Attach appropriate walking equipment before opening access in an unsecured area, without allowing escape or tangling. Keep identification, care contacts and relevant veterinary instructions available. Adjust the journey to comfort rather than forcing the planned distance.')],[
('Verifica equipo exacto','Pide modelo, talla, instalación y certificación o pruebas independientes. Compara con información publicada. Nombre similar, vídeo comercial o material no prueban resultado.'),('Instala según documentación','Sigue instrucciones de coche y equipo, anclajes y accesorios permitidos. No improvises extensiones: CPS advierte riesgos por movimiento extra. Arnés de paseo no es automáticamente retención vehicular.'),('Introduce gradualmente','Empieza cómodo con vehículo parado y equipo ajustado; después trayectos manejables. Observa angustia o malestar y consulta. No dejes desatendido ni consideres ventana abierta protección térmica.'),('Ejemplo previo','Anuncia prueba de choque sin talla ni instalación. Registra lagunas y verifica fabricante y fuente independiente. Esta guía no ensaya ni certifica choque.'),('Prepara paradas','Organiza agua, baño y lugar seguro. Coloca equipo de paseo antes de abrir en zona no cerrada, evitando escape o enredos. Lleva identificación y contactos. Adapta trayecto a comodidad.')],['Verify exact model, size and independent evidence.','Follow vehicle and restraint installation instructions.','Introduce travel gradually and observe comfort.','Plan water, secure stops and care contacts.'],['Verifica modelo, talla y evidencia.','Sigue instalación documentada.','Introduce trayecto y observa comodidad.','Planifica agua, paradas y contactos.'],[('Is any walking harness suitable for car restraint?','No. Check documented intended use, fit, installation and independent evidence.'),('Have you crash-tested the products in this guide?','No. This is an evidence-checking guide, not a test or certification.')],[('¿Cualquier arnés de paseo sirve?','No. Verifica uso, ajuste, instalación y pruebas.'),('¿Habéis hecho pruebas de choque?','No. Orientamos comprobación de evidencia sin ensayar ni certificar.')])
page(67,('Puppy food: check life-stage adequacy before marketing claims','Ask your veterinary team about an appropriate growth diet for your Doberman puppy. Compare the exact label and manufacturer information; a breed photo, ingredient slogan or growth supplement is not an adequacy statement.'),('Alimento de cachorro: revisa adecuación antes de publicidad','Consulta dieta de crecimiento apropiada. Compara etiqueta exacta y fabricante; foto de raza, eslogan o suplemento no son declaración de adecuación.'),[
('Identify the complete product','Record the exact name, formulation, nutritional adequacy statement and feeding instructions. In markets using AAFCO statements, check the stated life stage and whether growth of large-size dogs is included or excluded. Other markets use different labeling frameworks; ask your veterinary team to interpret the actual package.'),('Ask questions beyond the ingredient list','Use WSAVA’s selection questions to ask about formulation expertise, quality control and nutritional information. WSAVA publishes guidance rather than approving individual brands. Ingredient order alone does not establish the diet’s overall suitability or nutritional balance.'),('Build an individual feeding plan','Discuss growth, body condition, current intake and all treats or extras with your veterinarian. Feeding instructions are a starting reference, not a guaranteed portion for every puppy. Do not add calcium or other growth supplements without an individual professional recommendation.'),('A worked label check','Example: packaging says puppy on the front, but the adequacy statement or large-size growth qualification is unclear. Record the exact wording, ask the manufacturer for clarification and discuss it with your veterinary team. This is a verification task, not a ranking of the product or a diagnosis of deficiency.'),('Keep a useful record as needs change','Save the label and instructions, note amounts actually offered and include training food and extras. Review the plan as your puppy develops or if appetite, stool or comfort changes. Do not try to accelerate growth to match an online size table.')],[
('Identifica producto completo','Anota nombre, fórmula, declaración de adecuación e instrucciones. En mercados AAFCO, comprueba etapa y si incluye o excluye crecimiento de perros grandes. Otros mercados difieren: consulta envase real.'),('Pregunta más que ingredientes','Usa preguntas WSAVA sobre formulación, control y nutrición. WSAVA orienta, no aprueba marcas individuales. Orden de ingredientes no demuestra equilibrio ni adecuación.'),('Prepara plan individual','Consulta crecimiento, condición, ingesta y extras. Instrucciones son referencia inicial, no ración garantizada. No añadas calcio u otros suplementos sin recomendación individual.'),('Ejemplo de etiqueta','Dice cachorro delante, pero adecuación o crecimiento de perros grandes no está claro. Anota texto, pide aclaración al fabricante y consulta. Verifica, sin clasificar ni diagnosticar deficiencia.'),('Conserva registros','Guarda etiqueta, cantidades ofrecidas, premios y extras. Revisa conforme crece o cambia apetito, heces o comodidad. No aceleres para cumplir tablas de talla.')],['Save exact label and adequacy wording.','Ask about large-size growth suitability in the applicable market.','Discuss portions, body condition and extras.','Avoid unprescribed growth supplements.'],['Guarda etiqueta y adecuación.','Consulta crecimiento de talla grande según mercado.','Revisa raciones, condición y extras.','Evita suplementos sin indicación.'],[('Does WSAVA approve a list of puppy-food brands?','WSAVA provides evaluation guidance, not individual brand approval.'),('Should I add calcium to help my puppy grow?','Ask your veterinarian; do not add growth supplements without an individual recommendation.')],[('¿WSAVA aprueba marcas?','Publica orientación, no aprobación individual.'),('¿Añado calcio para crecer?','Consulta; no añadas suplementos sin indicación individual.')])
page(70,('Switching food: plan the change and record the response','Discuss why the diet is changing and what transition suits your dog. A generic mixing schedule cannot account for illness, a prescribed diet or every digestive response.'),('Cambiar alimento: planifica y registra respuesta','Consulta motivo y transición apropiada. Un calendario genérico no contempla enfermedad, dieta prescrita ni todas las respuestas digestivas.'),[
('Clarify the reason and instructions','Record the current and proposed foods and why a change is needed. Ask your veterinarian whether a gradual change is appropriate and what exceptions apply. A prescribed plan or suspected illness needs individual instructions rather than adapting an internet timetable on your own.'),('Prepare the records before changing','Save labels and record amounts, treats, supplements and relevant symptoms. Keep other unnecessary dietary changes limited so the observation remains useful. Check storage and product instructions and measure consistently using the method agreed with your veterinary team.'),('Follow the agreed progression','Use the individual plan and note what was actually offered at each step. Do not advance simply because a calendar day arrived if concerns develop. Persistent vomiting, diarrhea, poor intake or other worrying changes calls for veterinary advice; urgent signs need urgent assistance.'),('A worked food-and-response log','Example fields: date; exact food and amount offered; extras; appetite; stool observations; other signs; question for the veterinary team. A missed meal or stool change is an observation, not proof that one ingredient caused it. The log should help a professional interpret the pattern.'),('Review rather than repeatedly switching','Share the record if the change is difficult and ask how to proceed. Avoid cycling through diets in response to each isolated observation or changing medication without instruction. A successful transition means the individual plan is working, not that this food is best for every Doberman.')],[
('Aclara motivo e instrucciones','Anota alimentos actual y propuesto y razón. Consulta si procede cambio gradual y excepciones. Dieta prescrita o enfermedad requieren instrucciones, no calendario adaptado por cuenta propia.'),('Prepara registro','Guarda etiquetas, cantidades, premios, suplementos y signos. Limita otros cambios innecesarios. Revisa almacenamiento y mide con método acordado.'),('Sigue progresión individual','Anota lo realmente ofrecido. No avances por fecha si hay preocupaciones. Vómito, diarrea, mala ingesta u otros cambios persistentes requieren consejo; urgencias, ayuda urgente.'),('Ejemplo de registro','Fecha, producto y cantidad, extras, apetito, heces, otros signos y pregunta profesional. Un cambio no prueba causalidad de ingrediente. Ayuda a interpretar patrón.'),('Revisa en vez de cambiar repetidamente','Comparte si cuesta y consulta cómo seguir. Evita alternar por cada observación o modificar medicamentos. Que funcione no demuestra mejor alimento para todos.')],['Clarify why the diet is changing and obtain a plan.','Record exact foods, amounts and extras.','Observe response without diagnosing ingredient causes.','Pause progression and seek advice when concerns arise.'],['Aclara motivo y plan.','Registra producto, cantidad y extras.','Observa sin diagnosticar causas.','Consulta preocupaciones antes de avanzar.'],[('Must every dog follow the same transition schedule?','No. Ask for instructions appropriate to the dog and the reason for the change.'),('Does a stool change prove an allergy?','No. Describe the observation to your veterinary team rather than diagnosing from the log.')],[('¿Todos siguen el mismo calendario?','No. Consulta según perro y motivo.'),('¿Cambio de heces demuestra alergia?','No. Describe al veterinario sin diagnosticar por registro.')])
page(71,('Training treats: fit rewards into the whole diet','Choose rewards your dog values while accounting for meals, extras and individual restrictions. Practical training food should be suitable in size, ingredients and handling—not an unlimited addition to the day’s intake.'),('Premios de entrenamiento: intégralos en la dieta','Elige recompensas valoradas considerando comidas, extras y restricciones. Deben tener tamaño, ingredientes y manejo adecuados, sin añadirse ilimitadamente.'),[
('Count every edible extra','Include training rewards, table food, chews and food used to give medication when discussing the diet. Ask your veterinary team about an appropriate allowance for this dog. A product serving suggestion is not a universal training-food budget, particularly with growth or a prescribed diet.'),('Choose suitable size and ingredients','Check the label and avoid ingredients restricted in your dog’s care plan. Use an appropriate size and shape and supervise eating. Smaller practical portions may support repeated rewards, but do not cut or crumble a product in a way that creates an unsuitable choking risk.'),('Match the reward to the task','Notice what your dog values in the setting. Food, appropriate play or another comfortable outcome can support learning; increasing treat quantity is not the answer to every missed cue. Make the practice easier if distraction or distress prevents participation.'),('A worked reward record','Example: record food reserved from the usual ration, additional treat product, pieces actually used and the task practiced. Bring the full record to a diet conversation. This example does not prescribe calories or a number of treats, and it does not justify reducing a prescribed meal without guidance.'),('Keep preparation and storage safe','Follow storage instructions, wash hands and keep rewards away from unattended access. Share the daily plan with other caregivers so multiple sessions do not hide extra intake. Review appetite, condition and any concerns with the veterinary team rather than relying on a treat label to assess health.')],[
('Cuenta extras','Incluye premios, sobras, mordedores y comida para medicación. Consulta cantidad individual. La ración del envase no es presupuesto universal, especialmente en crecimiento o dieta prescrita.'),('Revisa tamaño e ingredientes','Comprueba etiqueta y restricciones. Usa forma y tamaño apropiados supervisando. Porciones prácticas pueden ayudar, pero no cortes de modo que cree riesgo de atragantamiento.'),('Adapta recompensa a tarea','Observa valor en ese entorno. Comida, juego adecuado u otro resultado cómodo apoyan aprendizaje; más premios no resuelven todo. Facilita práctica ante distracción o angustia.'),('Ejemplo de registro','Anota alimento de ración habitual reservado, producto extra, piezas usadas y tarea. Comparte registro completo. No prescribe calorías ni número ni justifica reducir comida prescrita sin orientación.'),('Prepara y guarda seguro','Sigue almacenamiento, lava manos y evita acceso desatendido. Comparte plan entre cuidadores para contar sesiones. Revisa apetito y condición con veterinario, no por etiqueta.')],['Include every edible reward in the diet record.','Check size, shape, ingredients and restrictions.','Keep practice manageable instead of adding unlimited treats.','Coordinate rewards across caregivers.'],['Incluye toda recompensa comestible.','Revisa forma, tamaño e ingredientes.','Facilita práctica sin premios ilimitados.','Coordina cuidadores.'],[('Is there one treat allowance for every Doberman?','No. Discuss the whole diet and individual needs with your veterinary team.'),('Can I use part of a meal for training?','Ask how to fit suitable food into the individual plan, especially with a prescribed diet.')],[('¿Hay cantidad única para todos?','No. Consulta dieta completa y necesidades.'),('¿Uso comida de una ración?','Consulta cómo integrarla, especialmente con dieta prescrita.')])
for lang in ('en','es'):
 for n in (67,70,71):
  c=COPY[f'DD-{n:03d}'][lang];c['asset_title']='Your diet-review checkpoints' if lang=='en' else 'Puntos para revisar la dieta'
  c['matrix']=[('Record','Exact label, actual intake and extras'),('Discuss','Individual needs with the veterinary team'),('Observe','Comfort and changes without diagnosing')] if lang=='en' else [('Registra','Etiqueta, ingesta real y extras'),('Consulta','Necesidades individuales al equipo'),('Observa','Comodidad y cambios sin diagnosticar')]
 COPY['DD-070'][lang]['log_fields']=['Date and exact food/amount','Treats, supplements and other extras','Appetite and stool observations','Other signs and question for the veterinary team'] if lang=='en' else ['Fecha, alimento y cantidad','Premios, suplementos y extras','Apetito y observación de heces','Otros signos y pregunta veterinaria']
